function process(arr){let r=0;for(let i=0;i<arr.length;i++)r+=arr[i];return r;}

// Readable but slightly slower
function processArray(array) {
  let result = 0;
  for (let i = 0; i < array.length; i++) {
    result += array[i];
  }
  return result;
}

// Readable and reasonably fast
function processArray(array) {
  return array.reduce((sum, value) => sum + value, 0);
}

// Decision: Choose readability unless profiling shows
// performance is critical and the optimization matters.

// Fast but unsafe
function parseUserInput(input) {
  return JSON.parse(input);
}

// Slower but safe
function parseUserInputSafe(input) {
  try {
    const parsed = JSON.parse(input);
    if (!isValidUserObject(parsed)) {
      throw new Error('Invalid user data');
    }
    return sanitize(parsed);
  } catch (error) {
    logError(error);
    return getDefaultUser();
  }
}

// Decision: External input needs validation,
// internal trusted data might skip checks.

// Simple but inflexible
function sendEmail(to, subject, body) {
  // Hardcoded email service
  emailService.send(to, subject, body);
}

// Flexible but complex
function sendEmail(to, subject, body, options = {}) {
  const provider = options.provider || config.defaultProvider;
  const template = options.template || 'default';
  const priority = options.priority || 'normal';

  if (provider === 'sendgrid') {
    return sendgridProvider.send({ to, subject, body, template, priority });
  } else if (provider === 'ses') {
    return sesProvider.send({ to, subject, body, template, priority });
  }
  // ... more providers
}

// Balanced: abstraction with reasonable defaults
function sendEmail(to, subject, body, provider = null) {
  const emailProvider = provider || getEmailProvider();
  return emailProvider.send(to, subject, body);
}
